const c = $input.first().json;
for (const k of ['window_minutes','step_seconds','threshold_percent','minimum_coverage','minimum_breach_fraction','minimum_sustained_minutes','worsening_delta_points']) if (!Number.isFinite(c[k])) throw new Error('Invalid numeric setting: ' + k);
if (!/^[a-z0-9_-]{1,50}$/.test(c.rule_key) || !String(c.promql).trim()) throw new Error('Set a stable rule key and a PromQL expression.');
if(c.window_minutes<5||c.window_minutes>120||c.step_seconds<30||c.step_seconds>300||c.minimum_sustained_minutes<1||c.minimum_sustained_minutes>c.window_minutes||c.minimum_coverage<0.5||c.minimum_coverage>1||c.minimum_breach_fraction<0.5||c.minimum_breach_fraction>1||c.threshold_percent<0||c.threshold_percent>100||c.worsening_delta_points<0) throw new Error('Capacity policy is outside the documented bounds.');
const end = Math.floor(Date.now()/1000/c.step_seconds)*c.step_seconds;
const span=c.window_minutes*60;
if(span%c.step_seconds!==0) throw new Error('Window duration must be divisible by query step.');
return [{json:{...c,start_seconds:end-2*span,mid_seconds:end-span,end_seconds:end,start_iso:new Date((end-2*span)*1000).toISOString(),end_iso:new Date(end*1000).toISOString()}}];

const c=$('Validate Policy Configurations').first().json;
const raw=$input.first().json;
if(raw.status!=='success'||raw.data?.resultType!=='matrix'||!Array.isArray(raw.data.result)) throw new Error('Expected a successful Prometheus matrix response. No capacity conclusion was made.');
const series=raw.data.result;
if(series.length>100) throw new Error('Query returned more than 100 series. Narrow the PromQL selector before running again.');
if(!series.length) return [{json:{rule_key:c.rule_key,outcome:'no_data',reason:'No matching metric series. Check collectors, organization, and PromQL metric names.',task_candidate:false}}];
const count=(c.window_minutes*60)/c.step_seconds;
function stats(samples,from,to) {
 const buckets=new Map();
 for(const p of samples) {
  if(!Array.isArray(p)||p.length<2) continue;
  const t=Number(p[0]); const v=Number(p[1]);
  if(!Number.isFinite(t)||!Number.isFinite(v)||String(p[1]).trim()===''||v<0||v>100||t<=from||t>to) continue;
  if(Math.abs(t/c.step_seconds-Math.round(t/c.step_seconds))>0.001) continue;
  buckets.set(t,v);
 }
 const ordered=[...buckets.entries()].sort((a,b)=>a[0]-b[0]);
 let trailing=0, cursor=to;
 while(buckets.has(cursor)&&buckets.get(cursor)>=c.threshold_percent){trailing++;cursor-=c.step_seconds;}
 const coverage=Math.min(1,ordered.length/count);
 return {count:ordered.length,coverage,average:ordered.length?ordered.reduce((a,b)=>a+b[1],0)/ordered.length:null,peak:ordered.length?Math.max(...ordered.map(p=>p[1])):null,latest:ordered.length?ordered[ordered.length-1][1]:null,fresh:ordered.length>0&&to-ordered[ordered.length-1][0]<=c.step_seconds,breach_fraction:ordered.filter(p=>p[1]>=c.threshold_percent).length/count,trailing_minutes:trailing*c.step_seconds/60};
}
const seen=new Set();
return series.map(s=>{
 const labels=s.metric||{}; const identity=Object.keys(labels).filter(k=>k!=='__name__').sort().map(k=>[k,String(labels[k])]);
 const key=c.rule_key+':'+JSON.stringify(identity);
 if(seen.has(key)) throw new Error('Duplicate metric identity; aggregate the query to one series per resource.'); seen.add(key);
 const current=stats(s.values||[],c.mid_seconds,c.end_seconds),previous=stats(s.values||[],c.start_seconds,c.mid_seconds);
 const valid=current.coverage>=c.minimum_coverage&&current.fresh;
 const baseline=previous.coverage>=c.minimum_coverage&&previous.fresh;
 const delta=valid&&baseline?current.average-previous.average:null;
 const sustained=valid&&current.breach_fraction>=c.minimum_breach_fraction&&current.trailing_minutes>=c.minimum_sustained_minutes;
 return {json:{rule_key:c.rule_key,resource_labels:labels,resource_key:key,outcome:!valid?'insufficient_data':sustained?'sustained_pressure':current.peak>=c.threshold_percent?'transient_pressure':'healthy',task_candidate:sustained,threshold_percent:c.threshold_percent,current,previous,delta_points:delta,trend:delta===null?'baseline_unavailable':delta>=c.worsening_delta_points?'worsening':delta<=-c.worsening_delta_points?'improving':'stable',checked_at:c.end_iso,promql:c.promql,window_minutes:c.window_minutes}};
});

return $input.all().map((item,i)=>{
 const r=item.json; if(!r.task_candidate) return {json:r,pairedItem:{item:i}};
 const encode=v=>encodeURIComponent(String(v)).replace(/[!'()*]/g,c=>'%'+c.charCodeAt(0).toString(16).toUpperCase());
 const labels=Object.keys(r.resource_labels).filter(k=>k!=='__name__').sort();
 const title='Capacity review: '+r.rule_key+' | '+(labels.map(k=>encode(k)+'='+encode(r.resource_labels[k])).join(';')||'aggregate');
 if(title.length>1000) throw new Error('Resource labels produce a task title over 1000 characters. Reduce labels in PromQL.');
 const round=v=>v===null?'unknown':Math.round(v*10)/10;
 const markdown=[
 '[OpenObserve capacity evidence - start]',
 'Review key: '+r.resource_key,
 'Resource: '+JSON.stringify(r.resource_labels),
 'Condition: sustained '+r.rule_key,
 'Threshold: '+r.threshold_percent+'%',
 'Current '+r.window_minutes+'-minute mean: '+round(r.current.average)+'%',
 'Previous mean: '+round(r.previous.average)+'%',
 'Change: '+round(r.delta_points)+' percentage points ('+r.trend+')',
 'Current coverage: '+Math.round(r.current.coverage*100)+'%',
 'Trailing time above threshold: '+r.current.trailing_minutes+' minutes',
 'Checked: '+r.checked_at,
 'PromQL: '+r.promql,
 '',
 'Review workload growth and resource allocation before changing infrastructure.',
 'Add personal notes outside these evidence markers. Keep the task title unchanged.',
 '[OpenObserve capacity evidence - end]'
 ].join('\n');
 return {json:{...r,review_key:r.resource_key,task_proposal:{title,bodyV2:{markdown}}},pairedItem:{item:i}};
});

const rows=$input.all().map(i=>i.json);
const counts={},crm={created:0,updated:0,preview:0,skipped:0};
for(const r of rows){counts[r.outcome]=(counts[r.outcome]||0)+1;if(!(r.crm_action in crm)) throw new Error('Missing CRM outcome.');crm[r.crm_action]++;}
return [{json:{status:'capacity_review_complete',counts,crm,task_candidates:rows.filter(r=>r.task_candidate).length,crm_tasks_written:crm.created+crm.updated,findings:rows}}];

const r=$('Batch Process Resources').itemMatching(0).json;
if(!r?.task_proposal) throw new Error('Missing current resource proposal.');
const matches=$input.all().map(i=>i.json).filter(x=>Object.keys(x).length);
if(matches.length>1) throw new Error('Multiple capacity tasks share this title. Resolve duplicates before rerunning.');
const existing=matches[0];
if(existing && (!existing.id || existing.title!==r.task_proposal.title)) throw new Error('Unexpected task lookup result. No write performed.');
let body=r.task_proposal.bodyV2.markdown;
if(existing){
 const old=existing.bodyV2?.markdown;
 const start='[OpenObserve capacity evidence - start]';
 const end='[OpenObserve capacity evidence - end]';
 if(typeof old!=='string'||old.split(start).length!==2||old.split(end).length!==2||old.indexOf(end)<old.indexOf(start)||!old.includes('Review key: '+r.review_key+'\n')) throw new Error('Existing task identity/evidence markers do not match. No write performed.');
 body=old.slice(0,old.indexOf(start))+body+old.slice(old.indexOf(end)+end.length);
}
return [{json:{...r,existing_task_id:existing?.id||null,update_payload:{bodyV2:{markdown:body}}}}];

const r=$('Plan Task Creation or Update').item.json;
if(!$json.id) throw new Error('Twenty did not return a task ID.');
return [{json:{...r,crm_action:'updated',crm_task_id:$json.id}}];

const r=$('Plan Task Creation or Update').item.json;
if(!$json.id) throw new Error('Twenty did not return a task ID.');
return [{json:{...r,crm_action:'created',crm_task_id:$json.id}}];
